  ('kushtia-general-hospital', 'hospital', 'কুষ্টিয়া জেনারেল হাসপাতাল', 'Kushtia General Hospital', array['sadar hospital','general hospital','সদর হাসপাতাল']::text[], 'কুষ্টিয়া শহরের সরকারি জেনারেল হাসপাতাল। জরুরি বিভাগ, বহির্বিভাগ, আন্তঃবিভাগ ও ব্লাড ব্যাংক সেবা এখানে পাওয়া যায়।', 'The government general hospital serving Kushtia town, with emergency, outpatient, inpatient and blood bank services.', 'হাসপাতাল রোড, কুষ্টিয়া সদর', 'Hospital Road, Kushtia Sadar', 'kushtia-sadar', null, null, true, '+880 1700-000-201', null, null, null, null, null, null, true, true, null, null, 'partial', 'dghs', 'https://dghs.gov.bd/', 'স্বাস্থ্য অধিদপ্তর (DGHS) তালিকা', 'Directorate General of Health Services listing', null, 'published', true),
  ('kushtia-medical-college-hospital', 'hospital', 'কুষ্টিয়া মেডিকেল কলেজ হাসপাতাল', 'Kushtia Medical College Hospital', array['kmch','medical college','মেডিকেল কলেজ']::text[], 'কুষ্টিয়া মেডিকেল কলেজের সংযুক্ত সরকারি হাসপাতাল। বিশেষায়িত বিভাগ, আইসিইউ ও শিক্ষানবিশ চিকিৎসা সেবা রয়েছে।', 'The teaching hospital attached to Kushtia Medical College, carrying specialist departments and intensive care.', 'জুগিয়া, কুষ্টিয়া সদর', 'Jugia, Kushtia Sadar', 'kushtia-sadar', null, null, true, '+880 1700-000-202', null, null, null, null, null, null, true, true, null, null, 'partial', 'dghs', 'https://dghs.gov.bd/', 'স্বাস্থ্য অধিদপ্তর (DGHS) তালিকা', 'Directorate General of Health Services listing', null, 'published', true),
